"""Restrict the existing directed-transition probes to operations generated by the literal four-column square. All four color-exchanging anti-bindings are tested. A directed triangle rotation outside the square is a positive control, not a derived flag adapter."""
from pathlib import Path
from itertools import permutations
from collections import Counter
import sys,json
D=Path(__file__).resolve().parent;sys.path.insert(0,str(D.parents[1]/'nima/checkers'))
from check_carrier_probe_adapter import group,transition,edges

def run():
    I=tuple(range(4));f=(1,0,3,2);h=(2,3,0,1);j=(0,2,1,3);G={I};todo=[I]
    for p in todo:
        for a in (f,h,j):
            q=tuple(a[x] for x in p)
            if q not in G:G.add(q);todo.append(q)
    src={'AB','BC','CA'};dst={'AD','DB','BA'};out=[]
    for p in permutations('ABCD'):
        r={p[i]:p[j[i]] for i in I};rev=lambda e:r[e[1]]+r[e[0]]
        if {rev(e) for e in src}!=dst or {rev(e) for e in dst}!=src:continue
        def action(g):return tuple('ABCD'.index(p[g[p.index(x)]]) for x in 'ABCD')
        def score(g):
            i=group.index(g);return tuple(int(transition[edges.index(e)].get(i,0)) for e in [(0,1),(1,0)])
        sq=Counter(score(action(g)) for g in G);full=Counter(map(score,group));assert set(sq)=={(0,0),(1,1)} and full[(1,0)]==full[(0,1)]==4
        control=score((1,2,0,3));assert control==(1,0);out.append(dict(binding=''.join(p),square={str(k):v for k,v in sq.items()},full={str(k):v for k,v in full.items()},ABC_rotation=control))
    assert len(out)==4;return out
if __name__=='__main__':
    out=run();print(out);(D/'ramsey_square_seam_probe.json').write_text(json.dumps(out)+'\n')
